(102, 'BADAN AMIL ZAKAT NASIONAL KABUPATEN PINRANG (BAZNAS)', 'Sebagai desainer di BAZNAS Kabupaten Pinrang, Anda diminta membuat poster digital untuk kampanye zakat. Apa yang paling penting diperhatikan?', 'Penggunaan font yang unik meskipun sulit dibaca', 1, 'Kombinasi warna yang menarik dan sesuai dengan branding BAZNAS', 4, 'Memasukkan banyak gambar tanpa hierarchy visual', 2, 'Desain monoton dengan satu warna saja', 3, 'core'),
(103, 'BADAN AMIL ZAKAT NASIONAL KABUPATEN PINRANG (BAZNAS)', 'Aplikasi apa yang paling efektif digunakan untuk membuat infografis laporan keuangan BAZNAS?', 'Paint dengan tools dasar', 2, 'PowerPoint dengan template default', 3, 'Adobe Illustrator atau Canva untuk desain yang profesional', 4, 'Microsoft Word dengan shapes sederhana', 1, 'core'),
(104, 'BADAN AMIL ZAKAT NASIONAL KABUPATEN PINRANG (BAZNAS)', 'Bagaimana cara meningkatkan engagement masyarakat melalui media sosial BAZNAS ?', 'Membuat konten visual menarik (video, infografis) dengan pesan yang jelas', 4, 'Memakai template yang sama terus-menerus ', 3, 'Hanya memposting teks panjang tanpa gambar', 1, 'Mengupload foto tanpa editing atau narasi', 2, 'core'),
(105, 'BADAN AMIL ZAKAT NASIONAL KABUPATEN PINRANG (BAZNAS)', 'Berapa jarak lokasi rumah siswa dengan kantor BAZNAS Kabupaten Pinrang?', ' 5–10 km', 3, '10–20 km', 2, 'Kurang dari 5 km', 4, 'Lebih dari 20 km', 1, 'secondary'),
(106, 'BADAN AMIL ZAKAT NASIONAL KABUPATEN PINRANG (BAZNAS)', 'Jika siswa harus datang ke BAZNAS untuk magang, transportasi apa yang paling efisien ?', 'Angkutan umum (jarak menengah)', 3, 'Ojek (jarak cukup jauh)', 2, 'Mobil pribadi (jarak sangat jauh)', 1, 'Jalan kaki/bersepeda (jarak sangat dekat)', 4, 'secondary'),
(107, 'BADAN KEPEGAWAIAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA (BKPSDM) KABUPATEN PINRANG', 'Pertanyaan tentang Aplikasi yang Digunakan di BKPSDM Kabupaten Pinrang ?', 'SAPK (Sistem Aplikasi Pegawai Negeri) atau SIPP (Sistem Informasi Kepegawaian)', 4, 'Microsoft World ', 2, 'Microsoft Excel sederhana tanpa database terintegrasi', 3, 'Aplikasi edit foto seperti Photoshop', 1, 'core'),
(108, 'BADAN KEPEGAWAIAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA (BKPSDM) KABUPATEN PINRANG', ' Sebagai desainer di BKPSDM, Anda diminta membuat infografis tentang rekruitmen CPNS. Apa yang paling penting ?', 'Banyak animasi yang memukau tapi tidak relevan', 2, 'Warna mencolok tapi tidak konsisten', 3, 'Desain jelas, hierarki visual baik, dan informasi mudah dipahami', 4, 'Hanya teks panjang tanpa ilustrasi', 1, 'core'),
(109, 'BADAN KEPEGAWAIAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA (BKPSDM) KABUPATEN PINRANG', 'Media sosial BKPSDM membutuhkan konten visual menarik. Tools apa yang paling tepat ?', 'Canva', 3, 'Adobe Photoshop/Adobe Illustrator untuk desain profesional', 4, 'Screenshot WhatsApp tanpa editing', 1, 'PowerPoint dengan template standar', 2, 'core'),
(110, 'BADAN KEPEGAWAIAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA (BKPSDM) KABUPATEN PINRANG', 'Berapa jarak rumah siswa dengan kantor BKPSDM Kabupaten ?', '≤ 5 km (sangat dekat)', 4, ' 5–10 km (cukup dekat)', 3, '10–20 km (jauh)', 2, '> 20 km (sangat jauh)', 1, 'secondary'),
(111, 'BADAN KEPEGAWAIAN DAN PENGEMBANGAN SUMBER DAYA MANUSIA (BKPSDM) KABUPATEN PINRANG', 'Jika siswa magang di BKPSDM 5 hari seminggu, transportasi apa paling efisien?', 'Jalan kaki/sepeda', 4, 'Mobil pribadi', 2, 'Angkot/ojol', 1, 'Motor pribadi', 3, 'secondary'),
(112, 'BANK NEGARA INDONESIA (BNI) PINRANG', 'Aplikasi apa yang PALING SERING digunakan oleh karyawan BNI untuk transaksi perbankan digital ?', 'Zoom (hanya untuk meeting virtual)', 3, 'Instagram (hanya untuk sosial media marketing)', 2, 'BNI Mobile Banking (aplikasi resmi untuk nasabah dan internal)', 4, 'WhatsApp (hanya untuk komunikasi umum) ', 1, 'core'),
(113, 'BANK NEGARA INDONESIA (BNI) PINRANG', 'Sebagai desainer di BNI Pinrang, Anda diminta membuat poster promo kartu kredit. Aspek apa yang PALING PENTING?', 'Kombinasi warna brand BNI (biru & kuning) + informasi jelas', 4, 'Gambar abstrak tanpa pesan produk', 1, 'Animasi berlebihan yang mengganggu fokus', 3, 'Teks panjang tanpa ilustrasi', 2, 'core'),
